import { t, L, esc, money, dictionary } from './i18n.js';
import { icon } from './icons.js';
import { courseCover, initialsAvatar } from './media.js';
let sequence=0;
const uid=p=>`${p}-${++sequence}`;
const safeHref=href=>typeof href==='string' && /^#\/(?:[^<>"'\s]*)$/.test(href)?href:'#/';
const attrs=data=>Object.entries(data??{}).filter(([k])=>['id','course-id','page','role','lang','theme','target','href','value','overlay'].includes(k)).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ');
const clamp=v=>Math.min(100,Math.max(0,Number(v)||0));
export function button({label,href=null,action=null,data={},variant='primary',disabled=false,disabledReason=''}) { const cls={primary:'btn-primary',secondary:'btn-secondary',ghost:'btn-ghost',danger:'btn-danger'}[variant]??'btn-primary';const reason=disabled?(disabledReason||t('disabled')):'';const text=esc(label);const markup=href&&!disabled?`<a class="btn ${cls}" href="${esc(safeHref(href))}">${text}</a>`:`<button type="button" class="btn ${cls}" ${action&&!disabled?`data-action="${esc(action)}"`:''} ${attrs(data)} ${disabled?`disabled title="${esc(reason)}"`:''}>${text}</button>`;return markup+(reason?`<small class="muted block">${esc(reason)}</small>`:''); }
export function iconButton({label,icon:iconName,action,data={},expanded=null,controls=null}) { return `<button type="button" class="icon-btn hover:bg-sand" aria-label="${esc(label)}" title="${esc(label)}" data-action="${esc(action)}" ${attrs(data)} ${expanded!==null?`aria-expanded="${!!expanded}"`:''} ${controls?`aria-controls="${esc(controls)}"`:''}>${icon(iconName)}</button>`; }
export function card({title='',subtitle='',body='',actions='',className=''}) { return `<section class="panel ${esc(className)}">${title?`<h2>${esc(title)}</h2>`:''}${subtitle?`<p class="muted mt-2">${esc(subtitle)}</p>`:''}<div class="${title||subtitle?'mt-4':''}">${body}</div>${actions?`<footer class="flex-row mt-5 pt-4 border-t border-border">${actions}</footer>`:''}</section>`; }
export function statCard({label,value,delta=null,icon:iconName=null,trend=[],href=null}) { return `<article class="panel">${iconName?icon(iconName):''}<p class="muted">${esc(label)}</p><p class="text-3xl font-semibold"><bdi>${esc(value)}</bdi></p>${delta!==null?`<p><bdi>${esc(Number(delta)>0?'+'+delta:delta)}</bdi></p>`:''}${trend.length?sparkline(trend,{label}):''}${href?button({label,href,variant:'ghost'}):''}</article>`; }
// Tone per exact state (SPEC §3.1): neutral draft/inactive, info in progress, warning waiting/held,
// success approved/complete, danger rejected/failed/revoked. Unknown keys are never shown as success.
const TONES={
 success:new Set(['active','approved','Approved','Published','published','paid','Paid','succeeded','verified','done','completed','released','read','sent','won','ready','resolved','recording_ready','recording_published']),
 warning:new Set(['pending','Pending','pending_verification','requested','submitted','Submitted','UnderReview','under_review','waiting','reserved','more_info_required','ChangesRequested','escalated','rescheduled','queued','invited','partially_refunded']),
 info:new Set(['in_progress','processing','Processing','assigned','live','scheduled','in_payout','initiated','recording_processing','open','graded']),
 danger:new Set(['rejected','Rejected','failed','Failed','revoked','lost','suspended']),
};
const TONE_ICONS={success:'checkCircle',warning:'clock',info:'refresh',danger:'x',neutral:'fileText'};
export function badge(status,{domain,size='sm'}={}) { const key=`status.${domain}.${status}`,known=Object.hasOwn(dictionary,key);const tone=known?Object.keys(TONES).find(k=>TONES[k].has(status))??'neutral':'neutral';return `<span class="chip tone-${tone} ${size==='lg'?'text-base':'text-sm'}">${icon(known?TONE_ICONS[tone]:'helpCircle',{size:14})}<span>${esc(t(known?key:'unknown'))}</span></span>`; }
export function table(columns,rows,{caption,rowKey='id',empty=null,actions=null}={}) { if(!rows.length)return empty??emptyState({title:t('empty')});const render=(c,r)=>c.render?c.render(r):esc(typeof r[c.key]==='object'?L(r[c.key]):r[c.key]);return `<table class="table-desktop"><caption class="text-start font-semibold py-3">${esc(caption??'')}</caption><thead><tr>${columns.map(c=>`<th scope="col" class="${c.align==='end'?'text-end':'text-start'}">${esc(c.label)}</th>`).join('')}${actions?'<th scope="col"><span class="sr-only">'+esc(t('details'))+'</span></th>':''}</tr></thead><tbody>${rows.map(r=>`<tr data-id="${esc(r[rowKey])}">${columns.map(c=>`<td class="${c.align==='end'?'text-end':'text-start'}">${render(c,r)}</td>`).join('')}${actions?`<td>${actions(r)}</td>`:''}</tr>`).join('')}</tbody></table><div class="table-mobile" role="list" aria-label="${esc(caption??'')}">${rows.map(r=>`<article class="mobile-record" role="listitem"><dl>${columns.map(c=>`<div><dt>${esc(c.label)}</dt><dd class="min-w-0">${render(c,r)}</dd></div>`).join('')}</dl>${actions?actions(r):''}</article>`).join('')}</div>`; }
export function tabs(items,active,{label,id='tabs'}={}) { return `<nav aria-label="${esc(label??t('menu'))}" class="flex-row border-b border-border pb-2">${items.map(x=>`<a id="${esc(id+'-'+x.id)}" href="${esc(safeHref(x.href))}" class="btn ${x.id===active?'btn-primary':'btn-ghost'}" ${x.id===active?'aria-current="page"':''}>${esc(x.label)}${x.count!==undefined?` <bdi>(${esc(x.count)})</bdi>`:''}</a>`).join('')}</nav>`; }
export function modal({id,title,body,footer='',size='md'}) { return `<dialog id="${esc(id)}" aria-labelledby="${esc(id)}-title" ${size==='lg'?'style="width:min(800px,calc(100vw - 32px))"':''}><div class="flex items-start justify-between gap-4 mb-4"><h2 id="${esc(id)}-title" tabindex="-1">${esc(title)}</h2>${iconButton({label:t('close'),icon:'x',action:'overlay.close',data:{id}})}</div><div class="stack">${body}</div>${footer?`<footer class="flex-row mt-6">${footer}</footer>`:''}</dialog>`; }
export function drawer({id,title,body,side='start'}) { return modal({id,title,body}).replace('<dialog ','<dialog class="drawer" '+(side==='end'?'style="inset-inline-end:0;inset-inline-start:auto" ':'')); }
export function emptyState({icon:iconName='search',title,description='',action=null}) { return `<article class="panel text-center py-12"><div class="flex justify-center text-primary mb-4">${icon(iconName,{size:40})}</div><h2>${esc(title)}</h2>${description?`<p class="muted max-w-xl mx-auto mt-3">${esc(description)}</p>`:''}${action?`<div class="mt-6">${button(action)}</div>`:''}</article>`; }
export function progressBar(value,{label='',showValue=true}={}) { const v=clamp(value);return `<div><div class="flex justify-between gap-3 text-sm"><span>${esc(label)}</span>${showValue?`<bdi>${Math.round(v)}%</bdi>`:''}</div><div role="progressbar" aria-label="${esc(label||t('progress'))}" aria-valuenow="${v}" aria-valuemin="0" aria-valuemax="100" class="h-2 rounded-full bg-sand mt-2 overflow-hidden"><div class="h-full bg-primary rounded-full" style="width:${v}%"></div></div></div>`; }
export function progressRing(value,{label='',size=80}={}) { const v=clamp(value),n=Math.max(32,Math.min(400,Number(size)||80));return `<svg xmlns="http://www.w3.org/2000/svg" width="${n}" height="${n}" viewBox="0 0 100 100" role="img" aria-label="${esc(label||t('progress'))}: ${Math.round(v)}%"><title>${esc(label||t('progress'))}</title><circle cx="50" cy="50" r="42" fill="none" stroke="var(--border)" stroke-width="7"/><circle cx="50" cy="50" r="42" fill="none" stroke="var(--primary)" stroke-width="7" stroke-dasharray="${v*2.639} 263.9" transform="rotate(-90 50 50)"/><text x="50" y="56" text-anchor="middle" fill="currentColor" font-size="20">${Math.round(v)}%</text></svg>`; }
export function sparkline(values,{label,width=120,height=32}={}) { const a=values.filter(Number.isFinite),w=Math.max(20,Math.min(1000,Number(width)||120)),h=Math.max(16,Math.min(400,Number(height)||32)),min=Math.min(...a),max=Math.max(...a);const points=a.map((v,i)=>`${4+i*(w-8)/Math.max(1,a.length-1)},${max===min?h/2:h-4-(v-min)/(max-min)*(h-8)}`).join(' ');return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label??t('progress'))}"><title>${esc(label??t('progress'))}</title><polyline points="${points}" fill="none" stroke="var(--primary)" stroke-width="2"/></svg>`; }
export function avatar(person,{size=40,showName=false}={}) { const name=L(person.name),n=Math.max(24,Math.min(200,Number(size)||40));return `<span class="inline-flex items-center gap-3 min-w-0"><img src="${initialsAvatar(name,person.id??name)}" width="${n}" height="${n}" style="width:${n}px;height:${n}px" class="rounded-full shrink-0" alt="${showName?'':esc(name)}">${showName?`<span>${esc(name)}</span>`:''}</span>`; }
export function courseCard(course,{href=null,progress=null,action=null}={}) { const url=safeHref(href??`#/course/${encodeURIComponent(course.id)}`),free=course.price_type==='free';return `<article class="panel card-link course-card flex flex-col min-w-0"><a href="${esc(url)}" tabindex="-1" aria-hidden="true" class="block relative"><img class="cover" src="${courseCover(course.id,course.subject?.id??course.subject_id)}" alt="" loading="lazy"><span class="cover-tag">${icon({live:'calendar',hybrid:'clock'}[course.mode]??'play',{size:14})}${esc(t('mode.'+course.mode))}</span></a><div class="p-4 flex flex-col flex-1 min-w-0"><p class="text-xs font-semibold text-primary">${esc(L(course.grade?.name))} · ${esc(L(course.subject?.name))}</p><h3 class="text-base mt-2"><a href="${esc(url)}">${esc(L(course.title))}</a></h3><p class="text-sm muted mt-2">${esc(L(course.teacher?.name))}</p>${progress!==null?`<div class="mt-4">${progressBar(progress,{label:t('progress')})}</div>`:''}<div class="flex items-center justify-between gap-3 mt-auto pt-4"><strong class="price ${free?'price-free':''}"><bdi>${esc(free?t('free'):money(course.price_baisa))}</bdi></strong>${action?button(action):`<a class="text-sm font-medium text-primary inline-flex items-center gap-1 min-h-11" href="${esc(url)}" aria-label="${esc(t('detailsFor',{title:L(course.title)}))}">${esc(t('details'))}${icon('chevronEnd',{size:16})}</a>`}</div></div></article>`; }
export function teacherCard(teacher,{href=null}={}) { const url=safeHref(href??`#/teacher/${encodeURIComponent(teacher.id)}`),name=L(teacher.name),verified=teacher.verification_state==='verified'&&teacher.credentials?.some(c=>c.verified);return `<article class="panel card-link teacher-card flex flex-col min-w-0"><div class="flex items-center gap-4 min-w-0"><img src="${initialsAvatar(name,teacher.id)}" width="64" height="64" style="width:64px;height:64px" class="rounded-full shrink-0" alt=""><div class="min-w-0"><h3 class="text-lg"><a href="${esc(url)}">${esc(name)}</a></h3>${verified?`<p class="verified-mark">${icon('checkCircle',{size:16})}<span>${esc(t('verified'))}</span></p>`:''}</div></div><p class="muted text-sm mt-4 clamp-3">${esc(L(teacher.bio))}</p>${teacher.qualifications?.length?`<ul class="flex flex-wrap gap-2 mt-4" aria-label="${esc(t('qualifications'))}">${teacher.qualifications.map(q=>`<li class="chip text-xs">${esc(L(q))}</li>`).join('')}</ul>`:''}<p class="mt-auto pt-5 flex items-center gap-2 text-sm font-medium text-primary">${icon('book',{size:16})}<span>${esc(t('publishedCount',{count:teacher.published_course_count??0}))}</span></p></article>`; }
export function lessonRow(lesson,{locked=false,preview=false,done=false,active=false,href=null,action=null}={}) { const label=locked?t('locked'):done?t('done'):preview?t('preview'):t('details');return `<li class="flex-row p-4 border-b border-border ${active?'bg-sand':''}" ${active?'aria-current="true"':''}>${icon(locked?'lock':done?'checkCircle':lesson.type==='video'?'play':'fileText')}<div class="flex-1 min-w-0"><h3>${esc(L(lesson.title))}</h3><p class="text-sm muted">${esc(t('duration',{count:Math.round(lesson.duration_seconds/60)}))} · ${esc(label)}</p></div>${button(locked?{label,action:'overlay.locked',variant:'secondary'}:action??{label,href:href??'#/explore',variant:'ghost'})}</li>`; }
export function pagination({page,total,pageSize,action='public.page'}) { const count=Math.max(1,Math.ceil(total/Math.max(1,pageSize))),p=Math.min(count,Math.max(1,page));const pages=Array.from({length:count},(_,i)=>i+1).filter(n=>n===1||n===count||Math.abs(n-p)<=2);return `<nav aria-label="${esc(t('pagination'))}" class="flex-row">${button({label:t('previous'),action,data:{page:p-1},disabled:p===1,disabledReason:t('previous'),variant:'secondary'})}${pages.map(n=>`<button type="button" class="btn ${n===p?'btn-primary':'btn-secondary'}" data-action="${esc(action)}" data-page="${n}" ${n===p?'aria-current="page"':''}>${n}</button>`).join('')}${button({label:t('next'),action,data:{page:p+1},disabled:p===count,disabledReason:t('next'),variant:'secondary'})}<p class="muted">${esc(t('results',{count:total}))}</p></nav>`; }
export function formField({id,name,label,type='text',value='',options=[],hint='',error='',required=false,disabled=false,min=null,max=null,step=null,rows=4}) { const safeId=id??uid('field');const description=[hint||type==='file'?safeId+'-hint':'',error?safeId+'-error':''].filter(Boolean).join(' ');const common=`name="${esc(name)}" ${required?'required':''} ${disabled?'disabled':''} ${description?`aria-describedby="${esc(description)}"`:''} ${error?'aria-invalid="true"':''}`;const inputAttrs=`id="${esc(safeId)}" ${common} class="field"`;let control;
 if(type==='radio')control=`<fieldset ${description?`aria-describedby="${esc(description)}"`:''}><legend class="font-medium mb-2">${esc(label)}</legend>${options.map((o,i)=>`<label class="flex-row min-h-11"><input type="radio" id="${esc(safeId+'-'+i)}" ${common} value="${esc(o.value)}" ${String(value)===String(o.value)?'checked':''} ${o.disabled?'disabled':''}>${esc(o.label)}</label>`).join('')}</fieldset>`;
 else if(type==='checkbox')control=`<label class="flex-row min-h-11"><input type="checkbox" id="${esc(safeId)}" ${common} ${value?'checked':''}>${esc(label)}</label>`;
 else {let field;if(type==='select')field=`<select ${inputAttrs}>${options.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''} ${o.disabled?'disabled':''}>${esc(o.label)}</option>`).join('')}</select>`;
 else if(type==='textarea')field=`<textarea ${inputAttrs} rows="${Math.max(1,Number(rows)||4)}">${esc(value)}</textarea>`;
 else {const typ=['text','email','password','number','date','datetime-local','file'].includes(type)?type:'text';field=`<input ${inputAttrs} type="${typ}" ${typ!=='file'&&typ!=='password'?`value="${esc(value)}"`:''} ${[['min',min],['max',max],['step',step]].filter(([,v])=>v!==null).map(([k,v])=>`${k}="${esc(v)}"`).join(' ')}>`;}control=`<label for="${esc(safeId)}" class="block font-medium mb-2">${esc(label)}${required?' *':''}</label>${field}`; }
 return `<div class="min-w-0">${control}${hint||type==='file'?`<p id="${esc(safeId)}-hint" class="text-sm muted mt-1">${esc(hint||t('fileHint'))}</p>`:''}${error?`<p id="${esc(safeId)}-error" class="text-sm text-accent mt-1">${esc(error)}</p>`:''}</div>`;
}
export function filterBar(fields,values,{action='public.filter',resetAction='public.resetFilters'}={}) { const id=uid('filters');const form=suffix=>`<form data-action="${esc(action)}" class="stack">${fields.map(f=>formField({...f,id:id+'-'+suffix+'-'+f.name,value:values[f.name]??''})).join('')}<button type="submit" class="btn btn-primary">${esc(t('apply'))}</button>${button({label:t('resetFilters'),action:resetAction,variant:'ghost'})}<div class="flex-row">${fields.filter(f=>values[f.name]).map(f=>`<span class="chip">${esc(f.label)}: ${esc(f.options?.find(o=>String(o.value)===String(values[f.name]))?.label??values[f.name])}</span>`).join('')}</div></form>`;return `<div class="filter-desktop">${form('desktop')}</div><div class="filter-mobile">${button({label:t('filters'),action:'overlay.open',data:{id},variant:'secondary'})}${drawer({id,title:t('filters'),body:form('mobile')})}</div>`; }
export function stepper(steps,current,{label}={}) { const index=steps.findIndex(s=>s.id===current);return `<ol aria-label="${esc(label??t('steps'))}" class="flex-row">${steps.map((s,i)=>`<li class="chip" ${i===index?'aria-current="step"':''}>${i<index?icon('check'):i+1} ${esc(s.label)} <span class="sr-only">${esc(t(i<index?'complete':i===index?'current':'upcoming'))}</span></li>`).join('')}</ol>`; }
export function toast({id,message,tone='info',action=null}) { return `<article id="${esc(id)}" class="toast" role="${tone==='danger'||tone==='error'?'alert':'status'}"><div class="flex-row">${icon(tone==='success'?'checkCircle':tone==='danger'||tone==='error'?'flag':'bell')}<p class="flex-1">${esc(message)}</p>${iconButton({label:t('dismiss'),icon:'x',action:'overlay.dismissToast',data:{id}})}</div>${action?button(action):''}</article>`; }
export function breadcrumb(items) { return `<nav aria-label="${esc(t('breadcrumb'))}"><ol class="flex-row text-sm muted">${items.map((x,i)=>`<li class="flex-row">${i?icon('chevronEnd',{size:14}):''}${x.href?`<a href="${esc(safeHref(x.href))}">${esc(x.label)}</a>`:`<span aria-current="page">${esc(x.label)}</span>`}</li>`).join('')}</ol></nav>`; }
export function pageHeader({title,subtitle='',actions='',breadcrumbs=[]}) { return `${breadcrumbs.length?breadcrumb(breadcrumbs):''}<header class="flex items-start justify-between gap-4 flex-wrap mb-8"><div class="min-w-0"><h1 tabindex="-1">${esc(title)}</h1>${subtitle?`<p class="muted mt-2">${esc(subtitle)}</p>`:''}</div>${actions?`<div class="flex-row">${actions}</div>`:''}</header>`; }
export function notice({title='',message,tone='info'}) { const toneClass={info:'tone-info',success:'tone-success',warning:'tone-warning',danger:'tone-danger'}[tone]??'tone-info';return `<aside class="rounded-xl p-4 ${toneClass}"><div class="flex-row">${icon(tone==='danger'?'flag':'helpCircle')}${title?`<strong>${esc(title)}</strong>`:''}</div><p class="mt-2">${esc(message)}</p></aside>`; }
// One overlay stack coordinates native modal top-layer behavior and nested dialogs.
const stack=[], timers=new Map();
const focusables=el=>[...el.querySelectorAll('a[href],button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(e=>!e.hidden && e.getClientRects().length);
function syncInert() { const top=stack.at(-1)?.dialog;for(const item of stack)item.dialog.inert=item.dialog!==top;for(const id of ['app','switcher-root','toast-root']) { const root=document.getElementById(id);if(root)root.inert=!!top&&!root.contains(top); } }
export function openOverlay(id,{returnFocus=document.activeElement}={}) { const dialog=document.getElementById(id);if(!dialog||dialog.open)return;const key=e=>{if(e.key==='Escape'){e.preventDefault();closeOverlay(id);}if(e.key==='Tab'){const all=focusables(dialog),first=all[0],last=all.at(-1);if(!first){e.preventDefault();dialog.focus();}else if(e.shiftKey&&(document.activeElement===first||!all.includes(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!all.includes(document.activeElement))){e.preventDefault();first.focus();}}};const cancel=e=>{e.preventDefault();closeOverlay(id);};const outside=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeOverlay(id);}};dialog.addEventListener('keydown',key);dialog.addEventListener('cancel',cancel);dialog.addEventListener('click',outside);stack.push({dialog,returnFocus,cleanup:()=>{dialog.removeEventListener('keydown',key);dialog.removeEventListener('cancel',cancel);dialog.removeEventListener('click',outside);}});dialog.showModal();syncInert();(dialog.querySelector('h2')??focusables(dialog)[0]??dialog).focus();document.querySelector(`[aria-controls="${CSS.escape(id)}"]`)?.setAttribute('aria-expanded','true'); }
export function closeOverlay(id) { const index=stack.findIndex(x=>x.dialog.id===id);if(index<0)return;while(stack.length>index){const item=stack.pop();item.cleanup();item.dialog.close();item.dialog.inert=false;document.querySelector(`[aria-controls="${CSS.escape(item.dialog.id)}"]`)?.setAttribute('aria-expanded','false');syncInert();if(item.returnFocus?.isConnected)item.returnFocus.focus();} }
export function showToast(message,{tone='info',action=null}={}) { const id=uid('toast'),root=document.getElementById('toast-root');root?.insertAdjacentHTML('beforeend',toast({id,message,tone,action}));if(!action&&!['danger','error'].includes(tone))timers.set(id,setTimeout(()=>removeToast(id),5000));return id; }
function removeToast(id) { clearTimeout(timers.get(id));timers.delete(id);document.getElementById(id)?.remove(); }
// Closes page/shell dialogs (the persistent switcher manages its own) and, unless kept, toasts.
export function disposeOverlays({keepToasts=false}={}) { const first=stack.findIndex(x=>!x.dialog.closest('#switcher-root'));if(first>=0)closeOverlay(stack[first].dialog.id);if(keepToasts)return;for(const id of [...timers.keys()])removeToast(id);document.getElementById('toast-root')?.replaceChildren(); }
export function registerActions(register) { register('overlay',{open:(_e,el)=>openOverlay(el.dataset.id),close:(_e,el)=>closeOverlay(el.dataset.id),dismissToast:(_e,el)=>removeToast(el.dataset.id),locked:()=>showToast(t('p2.lockedBody'),{tone:'info'})}); }
